'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { usePathname } from 'next/navigation';
import { Menu, X, CreditCard, Phone } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { NAVIGATION } from '@/lib/constants';

const Header: React.FC = () => {
  const pathname = usePathname();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const scrollTop = window.scrollY;
      setIsScrolled(scrollTop > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Fermer le menu mobile lors du changement de route
  useEffect(() => {
    setIsMenuOpen(false);
  }, [pathname]);

  const isActive = (href: string) => {
    if (href === '/') return pathname === '/';
    return pathname.startsWith(href);
  };

  return (
      <header className={`fixed top-0 left-0 right-0 backdrop-blur-sm z-50 transition-all duration-300 ${
          isScrolled
              ? 'bg-purple-950 shadow-lg'
              : 'bg-transparent'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            {/* Logo */}
            <Link href="/" className="flex items-center">
              <div className="flex items-center space-x-2">
                <Image
                    src={logo}
                    alt="logo"
                    width={150}
                    height={100}
                    className="w-[100px] md:w-[150px]"
                />
              </div>
            </Link>

            {/* Desktop Navigation */}
            <nav className="hidden md:flex items-center space-x-8">
              {navigation.map((item) => (
                  <Link
                      key={item.key}
                      href={item.href}
                      className={`transition-colors duration-200 font-medium ${
                          isActive(item.href)
                              ? isScrolled
                                  ? 'text-yellow-300'
                                  : 'text-purple-800'
                              : isScrolled
                                  ? 'text-white hover:text-yellow-300'
                                  : 'text-gray-700 hover:text-purple-800'
                      }`}
                  >
                    {t(item.key)}
                  </Link>
              ))}
            </nav>

            {/* Auth & Language Toggle & Mobile Menu */}
            <div className="flex items-center space-x-4">
              {/* Auth Buttons / User Menu */}
              {isAuthenticated && user ? (
                  <div className="relative hidden md:block">
                    <button
                        onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
                        className={`flex items-center space-x-2 pl-2 pr-4 py-2 rounded-full transition-colors duration-200 ${
                            isScrolled
                                ? 'bg-white/20 hover:bg-white/30 text-white'
                                : 'bg-purple-100 hover:bg-purple-200 text-purple-800'
                        }`}
                    >
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                          isScrolled ? 'bg-white/30' : 'bg-purple-200'
                      }`}>
                        <User className="w-4 h-4" />
                      </div>
                      <span className="text-sm font-medium">
                                        {user.firstName}
                                    </span>
                    </button>

                    {/* User Dropdown Menu */}
                    <AnimatePresence>
                      {isUserMenuOpen && (
                          <motion.div
                              initial={{ opacity: 0, y: -10 }}
                              animate={{ opacity: 1, y: 0 }}
                              exit={{ opacity: 0, y: -10 }}
                              className="absolute right-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-gray-100 overflow-hidden z-50"
                          >
                            <div className="p-4 border-b border-gray-100">
                              <p className="font-semibold text-gray-900">
                                {user.firstName} {user.lastName}
                              </p>
                              <p className="text-sm text-gray-500">{user.email}</p>
                            </div>
                            <div className="py-2">
                              <Link
                                  href="/dashboard"
                                  className="flex items-center px-4 py-2 text-gray-700 hover:bg-purple-50 transition-colors"
                                  onClick={() => setIsUserMenuOpen(false)}
                              >
                                <User className="w-4 h-4 mr-3" />
                                Mon espace
                              </Link>
                              <Link
                                  href="/dashboard/planning"
                                  className="flex items-center px-4 py-2 text-gray-700 hover:bg-purple-50 transition-colors"
                                  onClick={() => setIsUserMenuOpen(false)}
                              >
                                <Calendar className="w-4 h-4 mr-3" />
                                Planning
                              </Link>
                              <Link
                                  href="/dashboard/settings"
                                  className="flex items-center px-4 py-2 text-gray-700 hover:bg-purple-50 transition-colors"
                                  onClick={() => setIsUserMenuOpen(false)}
                              >
                                <Settings className="w-4 h-4 mr-3" />
                                Paramètres
                              </Link>
                            </div>
                            <div className="border-t border-gray-100">
                              <button
                                  onClick={() => {
                                    logout();
                                    setIsUserMenuOpen(false);
                                  }}
                                  className="flex items-center w-full px-4 py-2 text-red-600 hover:bg-red-50 transition-colors"
                              >
                                <LogOut className="w-4 h-4 mr-3" />
                                Déconnexion
                              </button>
                            </div>
                          </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
              ) : (
                  <div className="hidden md:flex items-center space-x-2">
                    <button
                        onClick={() => openModal(ModalType.Login)}
                        className={`px-4 py-2 rounded-lg font-medium transition-colors duration-200 ${
                            isScrolled
                                ? 'text-white hover:bg-white/10'
                                : 'text-purple-800 hover:bg-purple-50'
                        }`}
                    >
                      Connexion
                    </button>
                    <button
                        onClick={() => openModal(ModalType.Registration)}
                        className={`px-4 py-2 rounded-lg font-medium transition-colors duration-200 ${
                            isScrolled
                                ? 'bg-yellow-400 text-purple-900 hover:bg-yellow-300'
                                : 'bg-purple-800 text-white hover:bg-purple-900'
                        }`}
                    >
                      Rejoindre le Club
                    </button>
                  </div>
              )}

              <button
                  onClick={toggleLanguage}
                  className={`flex items-center space-x-1 px-3 py-1 rounded-full transition-colors duration-200 ${
                      isScrolled
                          ? 'bg-white/20 hover:bg-white/30 text-white'
                          : 'bg-purple-100 hover:bg-purple-200 text-purple-800'
                  }`}
              >
                <Globe className={`w-4 h-4 transition-colors duration-200 ${
                    isScrolled ? 'text-white' : 'text-purple-800'
                }`}/>
                <span className={`text-sm font-medium uppercase transition-colors duration-200 ${
                    isScrolled ? 'text-white' : 'text-purple-800'
                }`}>
                                {locale}
                            </span>
              </button>

              {/* Mobile menu button */}
              <button
                  onClick={() => setIsMenuOpen(!isMenuOpen)}
                  className={`md:hidden p-2 rounded-md transition-colors duration-200 ${
                      isScrolled
                          ? 'text-white hover:text-yellow-300 hover:bg-white/10'
                          : 'text-gray-700 hover:text-purple-800 hover:bg-gray-100'
                  }`}
              >
                {isMenuOpen ? <X className="w-6 h-6"/> : <Menu className="w-6 h-6"/>}
              </button>
            </div>
          </div>

          {/* Mobile Navigation */}
          {isMenuOpen && (
              <div className="md:hidden">
                <div className={`px-2 pt-2 pb-3 space-y-1 border-t transition-colors duration-200 ${
                    isScrolled
                        ? 'bg-purple-800/95 border-white/20'
                        : 'bg-white border-gray-200'
                }`}>
                  {navigation.map((item) => (
                      <Link
                          key={item.key}
                          href={item.href}
                          className={`block px-3 py-2 rounded-md transition-colors duration-200 ${
                              isActive(item.href)
                                  ? isScrolled
                                      ? 'text-yellow-300 bg-white/10'
                                      : 'text-purple-800 bg-purple-50'
                                  : isScrolled
                                      ? 'text-white hover:text-yellow-300 hover:bg-white/10'
                                      : 'text-gray-700 hover:text-purple-800 hover:bg-gray-50'
                          }`}
                          onClick={() => setIsMenuOpen(false)}
                      >
                        {t(item.key)}
                      </Link>
                  ))}

                  {/* Mobile Auth Buttons */}
                  {!isAuthenticated ? (
                      <div className="pt-4 space-y-2 border-t border-gray-200">
                        <button
                            onClick={() => { openModal(ModalType.Login); setIsMenuOpen(false); }}
                            className={`block w-full px-3 py-2 rounded-md text-center font-medium transition-colors duration-200 ${
                                isScrolled
                                    ? 'text-white bg-white/10 hover:bg-white/20'
                                    : 'text-purple-800 bg-purple-50 hover:bg-purple-100'
                            }`}
                        >
                          Connexion
                        </button>
                        <button
                            onClick={() => { openModal(ModalType.Registration); setIsMenuOpen(false); }}
                            className={`block w-full px-3 py-2 rounded-md text-center font-medium transition-colors duration-200 ${
                                isScrolled
                                    ? 'bg-yellow-400 text-purple-900 hover:bg-yellow-300'
                                    : 'bg-purple-800 text-white hover:bg-purple-900'
                            }`}
                        >
                          Rejoindre le Club
                        </button>
                      </div>
                  ) : (
                      <div className="pt-4 space-y-2 border-t border-gray-200">
                        <Link
                            href="/dashboard"
                            className={`flex items-center px-3 py-2 rounded-md transition-colors duration-200 ${
                                isScrolled
                                    ? 'text-white hover:bg-white/10'
                                    : 'text-gray-700 hover:bg-purple-50'
                            }`}
                            onClick={() => setIsMenuOpen(false)}
                        >
                          <User className="w-4 h-4 mr-3" />
                          {t('common.my_space')}
                        </Link>
                        <button
                            onClick={() => {
                              logout();
                              setIsMenuOpen(false);
                            }}
                            className={`flex items-center w-full px-3 py-2 rounded-md transition-colors duration-200 ${
                                isScrolled
                                    ? 'text-red-300 hover:bg-white/10'
                                    : 'text-red-600 hover:bg-red-50'
                            }`}
                        >
                          <LogOut className="w-4 h-4 mr-3" />
                          {t('common.logout')}
                        </button>
                      </div>
                  )}
                </div>
              </div>
          )}
        </div>
      </header>
  );
};

export default Header;